import{z as A,x as s,o as e,c as i,q as B,j as t,D as a,d as n,s as o,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"曲线策略的深化","description":"","frontmatter":{"title":"曲线策略的深化","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc-curve-strategies-deep.md","filePath":"quant/rc-curve-strategies-deep.md","lastUpdated":1791063341000}'),D={name:"quant/rc-curve-strategies-deep.md"};function d(p,E,c,u,C,h){const r=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=B('<h1 id="曲线策略的深化" tabindex="-1">曲线策略的深化 <a class="header-anchor" href="#曲线策略的深化" aria-label="Permalink to &quot;曲线策略的深化&quot;">​</a></h1><div class="epigraph"><p>曲线交易赌的从来不是收益率水平的方向，而是远期形状不会如期演化；把水平暴露留给对冲，剩下的部分才是你对形状的真实观点。</p><footer>—— 据 Litterman and Scheinkman, *Journal of Fixed Income*, 1991；Diebold and Li, *Journal of Econometrics*, 2006 整理</footer></div><p><a href="/quant/vt-exotic-risk-map">上一课</a>把波动率交易深化收束在一张奇异风险地图上：翼部、边界与对冲失配逐项入账，波动率一条线到此走完。本课开启「利率与信用深化」课程：先在利率侧走三课——曲线策略、Swaption、利率期权的波动——再转入信用与资金单元。曲线怎么建、风险怎么计量，已由<a href="/quant/curve-bootstrap">自举曲线</a>、<a href="/quant/nelson-siegel">Nelson-Siegel</a>与<a href="/quant/key-tenor-dv01">关键期限 DV01</a>讲清，本课默认你会；这里只问一件事：对形状的观点，怎么变成一笔 PnL 可归因、边界可控的持仓。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「五年内会陡」「二年十年会平」「五年点相对便宜」都是形状观点，但执行时你同时在承担两个暴露：水平的与形状的。若两条腿按名义金额而非 DV01 配权，平行上移会让「陡峭化」交易亏成一笔变相的空头久期；若蝶式三腿照抄 1-2-1 的名义权重，中点 DV01 与两翼之和并不相等，你买的其实是一笔斜率加水平的混合仓位。缺口因此不在观点，而在三件事：把观点从水平暴露里剥离的加权方式、把持有收益与形状变化分开的 carry-roll 分解、以及由此得到的进出场判据。</p><p><span class="marginnote">DV01 翻译一下：收益率变动一个基点（0.01%）时，持仓价值变多少——它是「对利率有多敏感」的尺子。说两腿 DV01 相等，意思是利率平移时一腿的亏恰好被另一腿的赚抵消，剩下的盈亏才真正只来自形状变化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一规则是风险中性而非金额中性：两腿 DV01 相等，\\(D_1 N_1 = D_2 N_2\\)，名义比随久期自动倒挂。表达陡峭化时先决定按收益率差还是按远期差报价——后者把滚动收益也押进观点里。蝶式让中腿 DV01 等于两翼之和；1-2-1 只在两翼 DV01 恰好相等的期限组合里近似成立，通常要用 DV01 回归或<a href="/quant/curve-pca">曲线主成分</a>的残差来定权，<a href="/quant/curve-butterfly">曲线蝶式交易</a>一课给过基础版，本课强调的是权重选择本身就是观点：DV01 权重押「局部曲率」，PCA 残差权重押「相对因子模型的便宜」。进出场判据来自 carry-roll 分解：若曲线按远期演化，任何 DV01 中性的形状仓位一阶不亏不赚——远期就是盈亏平衡线。所以建仓的正当理由是「市场隐含的形状变化比我的观点保守」，而不是「这形态看起来歪」。</p><p><span class="marginnote">数字实例：做 2s10s DV01 中性陡峭化。设 2 年腿每百万名义的 DV01 约 0.02、10 年腿约 0.08，则名义比要 4:1——空 10 年 100 万，就得多 2 年 400 万。若按 1:1 名义配，等于偷偷扛了一大笔变相空头久期，曲线没动、整体利率涨一点就先亏。</span></p>',9)),(e(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VIEW%5B%22%E5%BD%A2%E7%8A%B6%E8%A7%82%E7%82%B9%EF%BC%9A%E9%99%A1%E5%B3%AD%E5%8C%96%20%2F%20%E8%9D%B6%E5%BC%8F%22%5D%20--%3E%20W%5B%22DV01%20%E4%B8%AD%E6%80%A7%E9%85%8D%E6%9D%83%22%5D%0A%20%20W%20--%3E%20HEDGE%5B%22%E4%B8%80%E9%98%B6%E6%B0%B4%E5%B9%B3%E6%9A%B4%E9%9C%B2%E6%B8%85%E9%9B%B6%22%5D%0A%20%20W%20--%3E%20CR%5B%22carry%20%E4%B8%8E%20roll%20%E5%88%86%E8%A7%A3%22%5D%0A%20%20CR%20--%3E%20BE%5B%22%E8%BF%9C%E6%9C%9F%E6%BC%94%E5%8C%96%20%3D%20%E7%9B%88%E4%BA%8F%E5%B9%B3%E8%A1%A1%22%5D%0A%20%20BE%20--%3E%20JUDGE%7B%22%E9%9A%90%E5%90%AB%E5%BD%A2%E7%8A%B6%E5%8F%98%E5%8C%96%20vs%20%E8%87%AA%E8%BA%AB%E8%A7%82%E7%82%B9%22%7D%0A%20%20JUDGE%20--%3E%7C%22%E8%A7%82%E7%82%B9%E6%9C%89%E8%BE%B9%E9%99%85%22%7C%20ENTER%5B%22%E5%BB%BA%E4%BB%93%E5%B9%B6%E9%80%90%E6%97%A5%E5%BD%92%E5%9B%A0%22%5D%0A%20%20JUDGE%20--%3E%7C%22%E6%97%A0%E8%BE%B9%E9%99%85%22%7C%20WAIT%5B%22%E4%B8%8D%E8%BF%9B%E5%9C%BA%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>carry-roll 能精确分解，是因为<a href="/quant/curve-bootstrap">自举</a>给出的远期已经把「持有到远期日」的路径写死：持有收益等于票息利差加上沿曲线下滑的 roll，两者由同一组远期决定，不是两笔独立押注。蝶式的 PnL 对水平冲击一阶为零，剩下二阶凸性与曲率变化；这解释了蝶式为什么天然是「凸性加曲率」的组合，也解释了它为什么对折缝敏感——<a href="/quant/key-tenor-dv01">关键期限 DV01</a>的分桶在这里比平行 01 有用得多。归因时还要把<a href="/quant/swap-spread">互换利差</a>单独列账：国债蝶式与互换蝶式在危机里方向相反，混在一起归因，会把信用因素误记成利率观点的盈亏。</p>',2)),(e(),t(l,null,{default:a(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20FW%5B%22%E8%87%AA%E4%B8%BE%E7%BB%99%E5%87%BA%E4%B8%80%E6%95%B4%E7%BB%84%E8%BF%9C%E6%9C%9F%22%5D%20--%3E%20CR%5B%22%E6%8C%81%E6%9C%89%E6%94%B6%E7%9B%8A%20%3D%20%E7%A5%A8%E6%81%AF%E5%88%A9%E5%B7%AE%20%2B%20%E6%B2%BF%E6%9B%B2%E7%BA%BF%E4%B8%8B%E6%BB%91%E7%9A%84%20roll%22%5D%0A%20%20CR%20--%3E%20BE%5B%22%E8%BF%9C%E6%9C%9F%E6%BC%94%E5%8C%96%E6%97%B6%E4%B8%80%E9%98%B6%E4%B8%8D%E4%BA%8F%E4%B8%8D%E8%B5%9A%20%3D%20%E7%9B%88%E4%BA%8F%E5%B9%B3%E8%A1%A1%E7%BA%BF%22%5D%0A%20%20BF%5B%22%E8%9D%B6%E5%BC%8F%EF%BC%9A%E6%B0%B4%E5%B9%B3%E5%86%B2%E5%87%BB%E4%B8%80%E9%98%B6%E4%B8%BA%E9%9B%B6%22%5D%20--%3E%20SEC%5B%22%E5%89%A9%E4%B8%8B%E5%87%B8%E6%80%A7%E4%B8%8E%E6%9B%B2%E7%8E%87%E5%8F%98%E5%8C%96%22%5D%0A%20%20SEC%20--%3E%20KINK%5B%22%E5%AF%B9%E6%8A%98%E7%BC%9D%E6%95%8F%E6%84%9F%EF%BC%8C%E7%94%A8%E5%88%86%E6%A1%B6%20DV01%20%E9%87%8F%22%5D%0A%20%20SS%5B%22%E4%BA%92%E6%8D%A2%E5%88%A9%E5%B7%AE%E5%8D%95%E5%88%97%E8%B4%A6%E6%88%B7%22%5D%20--%3E%20MIX%5B%22%E4%B8%8E%E5%9B%BD%E5%80%BA%E8%9D%B6%E5%BC%8F%E5%8D%B1%E6%9C%BA%E4%B8%AD%E6%96%B9%E5%90%91%E7%9B%B8%E5%8F%8D%22%5D%0A%20%20MIX%20--%3E%20ATTR%5B%22%E6%B7%B7%E5%BD%92%E5%9B%A0%E4%BC%9A%E6%8A%8A%E4%BF%A1%E7%94%A8%E8%AE%B0%E6%88%90%E5%88%A9%E7%8E%87%E8%A7%82%E7%82%B9%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">同一个「五年点便宜」，用 2s5s10s 与 5s10s30s 表达是两笔不同的交易：前者押短中段的折缝，后者押中长段的隆起。两翼 DV01 相等时 1-2-1 名义权重大致成立，但三十年腿久期长，等 DV01 之下名义比常常远离 1:2:1，照抄教科书权重会留下一阶水平暴露。</span></p><p><span class="marginnote">常见误区：以为「曲线只要按远期走，形状仓就稳赚」。远期演化只是盈亏平衡线——一阶不亏不赚，本身不是利润来源。进场的正当理由只有一个：市场隐含的形状变化比你的观点保守，也就是你远比远期更陡（或更平），且拿得出证据。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写融资细节：回购成本与互换利差的资金面驱动留给抵押品一课，这里只要求把融资利差从形状观点的盈亏里剔出去。模型上的 rich/cheap 相对 <a href="/quant/nelson-siegel">Nelson-Siegel</a> 这类参数族而言：参数族表达不了的形状（双隆起、深折缝）会被误判成便宜，要补 Svensson 项或改用分段判据。抵押支持债券对冲盘对中段的持续扭曲是供给不是错价，拿均值回复去赌它会反复止损。最后，DV01 中性只在进场瞬间成立：权重随曲线移动漂移，再平衡的频率是交易成本与形状暴露之间的取舍，没有一劳永逸的中性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>形状观点必须配 DV01 中性权重，名义权重会把陡峭化变成变相的水平赌注。</li><li>蝶式权重是观点的一部分：DV01 权重、回归权重与 PCA 残差权重押的是不同对象。</li><li>远期是形状交易的盈亏平衡线，carry-roll 分解给出进出场判据，不是事后解释。</li><li>归因要把互换利差、折缝桶与融资成本分开，否则信用与供给会被记成利率观点。</li><li>出处：Litterman and Scheinkman, <em>Journal of Fixed Income</em>, 1991；Diebold and Li, <em>Journal of Econometrics</em>, 2006；曲线构建与计量见本栏自举、Nelson-Siegel、关键期限 DV01 三课。</li></ul>',6))])}const f=A(D,[["render",d]]);export{_ as __pageData,f as default};
